    return sum;
}

// Function to calculate the sum of values of toys given to Bob
int sumBob(int N, char S[]) {
    int sum = 0;
    for (int i = 0; i < N; i++) {
        if (S[i] == '0') {
            sum += i + 1; // Assuming the value of the i-th toy is i+1
        }
    }
    return sum;
}

// Function to check if the distribution is fair
int isFair(int N, char S[]) {
    int maxVal = 0;
    for (int i = 0; i < N; i++) {
        if (S[i] == '1' || S[i] == '0') {
            maxVal = fmax(maxVal, i + 1); // Assuming the value of the i-th toy is i+1
        }
    }

    int aliceSum = sumAlice(N, S);
    int bobSum = sumBob(N, S);

    return abs(aliceSum - bobSum) <= maxVal;
}

