// Load the BlenderBot-400M Distill model
const blenderbot = await import('@tensorflow-models/transformers').then((module) => module.BlenderBot400M);

// Function to send input to the model and display the output
async function sendMessage() {
    const userInput = document.getElementById('user-input').value;
    if (!userInput.trim()) return;

    // Send input to the model
    const result = await blenderbot.predict(userInput);
    const response = result[0].text;

    // Display the response in the chat history
