To read network packets from a socket on port 888, you can use the `recvfrom` function in C++. Here's an example code:

```cpp
#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main() {
    int sockfd;
    struct sockaddr_in server_addr;

    // Create a socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) == -1) {
        std::cerr << "Error creating socket" << std::endl;
        return 1;
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(888);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        std::cerr << "Error connecting to server" << std::endl;
        close(sockfd);
        return 1;
    }

    char buffer[1024];
    ssize_t bytes_received = recvfrom(sockfd, buffer, sizeof(buffer), 0, NULL, NULL);

    if (bytes_received == -1) {
        std::cerr << "Error receiving data" << std::endl;
        close(sockfd);
        return 1;
    }

    std::cout << "Received: " << buffer << std::endl;

    // Close the socket
    close(sockfd);

    return 0;
}
```

This code creates a UDP socket and connects it to the server running on port 888. It then reads a packet of data from the server and prints it out. You can modify this code to suit your needs.

