```python
import web3
from web3 import Web3
from eth_account import Account
from eth_account.signers.local import LocalAccount
from eth_typing import Address
from eth_utils import keccak
from typing import List, Dict

# Constants
BLOCKCHAIN_URL = 'https://mainnet.infura.io/v3/YOUR_INFURA_PROJECT_ID'
DEPOSIT_AMOUNT_PER_BYTE = 0.001  # Example: $0.001 per byte
LIFETIME_BLOCKS = 5  # Example: 5 blocks before expiration
FEE_PER_ACCESS = 0.0001  # Example: $0.0001 per access

class DataStorageBlockchain:
    def __init__(self):
        self.web3 = Web3(Web3.HTTPProvider(BLOCKCHAIN_URL))
        if not self.web3.isConnected():
            raise Exception("Failed to connect to the blockchain")

        self.nodes = {}
        self.data_storage_map = {}

    def create_node(self, address: str, private_key: str):
        account = Account.from_key(private_key)
        self.nodes[address] = {
            'account': account,
            'data_storage_deposit': 0,
            'data_storage_map': {},
            'lifetime_blocks': LIFETIME_BLOCKS
        }
        return self.nodes[address]

    def deposit_data(self, node_address: str, data: str, data_size: int, data_lifetime: int):
        if node_address not in self.nodes:
            raise ValueError("Node does not exist")

        deposit_amount = DEPOSIT_AMOUNT_PER_BYTE * data_size
        self.nodes[node_address]['data_storage_deposit'] += deposit_amount

        if data_lifetime > 0:
            self.nodes[node_address]['lifetime_blocks'] = data_lifetime

        self.store_data(node_address, data)

    def store_data(self, node_address: str, data: str):
        if node_address not in self.nodes:
            raise ValueError("Node does not exist")

        block_number = self.web3.eth.get_block_number()
        data_hash = keccak(data.encode()).hex()

        if data_hash not in self.data_storage_map:
            self.data_storage_map[data_hash] = []

        self.data_storage_map[data_hash].append({
            'node_address': node_address,
            'block_number': block_number
        })

    def get_data(self, node_address: str, data_hash: str) -> str:
        if node_address not in self.nodes:
            raise ValueError("Node does not exist")

        if data_hash not in self.data_storage_map:
            raise ValueError("Data not found")

        for entry in self.data_storage_map[data_hash]:
            if entry['node_address'] == node_address:
                return self.web3.eth.get_block(entry['block_number']).transactions[entry['block_number']].input.decode('utf-8')

        raise ValueError("Data not found")

    def delete_data(self, node_address: str, data_hash: str):
        if node_address not in self.nodes:
            raise ValueError("Node does not exist")

        if data_hash not in self.data_storage_map:
            raise ValueError("Data not found")

        self.data_storage_map.pop(data_hash)

    def calculate_fee(self, node_address: str, data_hash: str) -> float:
        if node_address not in self.nodes:
            raise ValueError("Node does not exist")

        if data_hash not in self.data_storage_map:
            raise ValueError("Data not found")

        fee_per_access = FEE_PER_ACCESS
        total_fees = 0

        for entry in self.data_storage_map[data_hash]:
            if entry['node_address'] != node_address:
                total_fees += fee_per_access

        return total_fees

# Example usage
