    hid_t dataspace_id;
    hid_t datatype_id;

    // Create a new file
    if ((file_id = H5Fcreate("data.h5", H5F_ACC_TRUNC, H5P_DEFAULT, H5P_DEFAULT)) < 0) {
        fprintf(stderr, "Could not create file\n");
        return -1;
    }

    // Create a new dataspace
    if ((dataspace_id = H5Screate_simple(1, dims, NULL)) < 0) {
        fprintf(stderr, "Could not create dataspace\n");
        return -1;
    }

    // Create a new datatype
    if ((datatype_id = H5Tcreate(H5T_COMPOUND, sizeof(Data))) < 0) {
        fprintf(stderr, "Could not create datatype\n");
        return -1;
    }

    // Set the size of the datatype
    if (H5Tset_size(datatype_id, H5T_VARIABLE) < 0) {
        fprintf(stderr, "Could not set size of datatype\n");
        return -1;
    }

    // Set the type of the first element of the datatype
    if (H5Tset_type(datatype_id, H5T_NATIVE_DOUBLE) < 0) {
        fprintf(stderr, "Could not set type of first element of datatype\n");
        return -1;
    }

    // Set the type of the second element of the datatype
    if (H5Tset_type(datatype_id, H5T_NATIVE_INT) < 0) {
        fprintf(stderr, "Could not set type of second element of datatype\n");
        return -1;
    }

    // Close the datatype
    if (H5Tclose(datatype_id) < 0) {
        fprintf(stderr, "Could not close datatype\n");
        return -1;
    }

    // Close the dataspace
    if (H5Sclose(dataspace_id) < 0) {
        fprintf(stderr, "Could not close dataspace\n");
        return -1;
    }

    // Close the file
    if (H5Fclose(file_id) < 0) {
        fprintf(stderr, "Could not close file\n");
        return -1;
    }

    return 0;
}
```

In this example, we create a new file, a new dataspace, and a new datatype using the `H5Fcreate`, `H5Screate_simple`, and `H5Tcreate` functions, respectively. We then set the size of the datatype to be variable using the `H5Tset_size` function with the `H5T_VARIABLE` constant. We also set the type of the first element of the datatype to be `double` using the `H5Tset_type` function with the `H5T_NATIVE_DOUBLE` constant. Finally, we close the datatype using the `H5Tclose` function.

