  setupFilesAfterEnv: ['./mocks/setupMocks.js'],
};
```

In `setupMocks.js`, you can set up the mocks:

```javascript
// mocks/setupMocks.js
const { expect } = require('chai');
const { describe, it } = require('mocha');

describe('Setup Mocks', () => {
  beforeEach(() => {
    // Mock a module
    const originalModule = require('original-module');
    const mockedModule = {
      someMethod: jest.fn(),
    };
    Object.assign(originalModule, mockedModule);
  });

  afterEach(() => {
    // Restore the original module
    delete require.cache[require.resolve('original-module')];
  });
});
```

#### 2. Mocking in Test Files

In your test files, you can use `jest.mock()` to mock specific modules:

```javascript
// tests/testFile.js
import { someFunction } from 'original-module';

describe('Test File', () => {
  it('should call the mocked method', () => {
    const originalModule = require('original-module');
    const mockedModule = {
      someMethod: jest.fn(),
    };
    Object.assign(originalModule, mockedModule);

    someFunction();

    expect(mockedModule.someMethod).toHaveBeenCalled();
  });
});
```

### Explanation

- **`setupFilesAfterEnv`**: This option runs a script after all other setup files have been loaded. The script can be used to set up global mocks or other initializations.
- **`jest.mock()`**: This function is used to mock a module in a test file. It allows you to replace the actual module with a mock implementation.

By combining these two approaches, you can ensure that your tests are isolated and that the mocks are applied correctly.

