```typescript
class Tcp {
    private _payload: Uint8Array;

    constructor(payload: Uint8Array) {
        this._payload = payload;
    }

    // Method to send data over TCP
    async send(data: Uint8Array): Promise<void> {
        const buffer = Buffer.from(this._payload);
        const socket = new Socket(); // Assuming you have a Socket class for TCP communication

        await socket.write(buffer, 0, data.length);
    }

    // Method to receive data over TCP
    async receive(): Promise<Uint8Array> {
        const buffer = Buffer.alloc(1024); // Allocate a buffer for receiving data
        const socket = new Socket();

        return new Promise((resolve, reject) => {
            socket.on('data', (chunk) => {
                resolve(chunk);
            });

            socket.on('error', (err) => {
                reject(err);
            });

            socket.on('close', () => {
                resolve(null);
            });

            socket.connect();
        });
    }
}

