func setupGaussianBlur(imagePath: String, context: MTLContext) -> MTLTexture? {
    // Load the image
    let image = UIImage(named: imagePath)?.cgImage
    guard let cgImage = image else { return nil }

    // Create a texture from the image
    let size = CGSize(width: cgImage.width, height: cgImage.height)
    let textureDescriptor = MTLTextureDescriptor.texture2DDescriptor(
        size: size,
        format: .rgba8Unorm,
        usage: [.shaderRead, .shaderWrite],
        storageMode: .shared
    )
    let texture = try! context.makeTexture(descriptor: textureDescriptor)

    // Copy the image data to the texture
    let sourceRect = CGRect(x: 0, y: 0, width: size.width, height: size.height)
    let destinationRect = CGRect(x: 0, y: 0, width: size.width, height: size.height)
    let sourceData = cgImage.dataProvider?.data as! [UInt8]
    let destinationData = texture.contentsOfRegion(destinationRect)
    let sourceBytesPerRow = Int(cgImage.bytesPerRow)
    let destinationBytesPerRow = Int(texture.getBytes(&destinationData!, bytesPerRow: sourceBytesPerRow, from: sourceRect, to: destinationRect))

    return texture
}
```

