```typescript
import * as tf from '@tensorflow/tfjs';

// Define the RNN model
class SimpleRNN {
    private rnn: tf.RNN;

    constructor(inputSize: number, hiddenSize: number, outputSize: number) {
        // Initialize the RNN with input size, hidden size, and output size
        this.rnn = tf.rnn({
            type: 'LSTM',
            units: hiddenSize,
            returnSequence: true
        });
    }

    // Forward pass through the RNN
    public forward(inputs: tf.Tensor2D): tf.Tensor2D {
        const [inputLengths] = inputs.shape;
        const output = this.rnn(inputs, { inputLengths });

        // The output is a sequence of sequences, so we need to flatten it
        const flattenedOutput = output.flatten();

        return flattenedOutput;
    }
}

// Example usage
