fn month_to_number(month: &str) -> Result<u32, &'static str> {
    let months = [
        ("January", 1),
        ("February", 2),
        ("March", 3),
        ("April", 4),
        ("May", 5),
        ("June", 6),
        ("July", 7),
        ("August", 8),
        ("September", 9),
        ("October", 10),
        ("November", 11),
        ("December", 12),
    ];

    for (month_str, number) in months.iter() {
        if month_str == month {
