Here is a complete example of an R Shiny app that visualizes the `mtcars` dataset:

```r
# Load necessary libraries
library(shiny)
library(ggplot2)

# Define the UI
ui <- fluidPage(
  titlePanel("Mtcars Dataset Visualization"),

  sidebarLayout(
    sidebarPanel(
      selectInput(inputId = "variable", 
                  label = "Select a variable:", 
                  choices = names(mtcars), 
                  selected = "mpg")
    ),

    mainPanel(
      plotOutput(outputId = "plot")
    )
  )
)

# Define the server logic
server <- function(input, output) {

  # Reactive expression to get the selected variable
  selected_variable <- reactive({
    if (input$variable == "mpg") {
      mtcars$mpg
    } else if (input$variable == "hp") {
      mtcars$hp
    } else if (input$variable == "disp") {
      mtcars$disp
    } else if (input$variable == "drat") {
      mtcars$drat
    } else if (input$variable == "wt") {
      mtcars$wt
    } else if (input$variable == "qsec") {
      mtcars$qsec
    } else if (input$variable == "vs") {
      mtcars$vs
    } else if (input$variable == "am") {
      mtcars$am
    } else if (input$variable == "gear") {
      mtcars$gear
    } else if (input$variable == "carb") {
      mtcars$carb
    }
  })

  # Output the plot
  output$plot <- renderPlot({
    ggplot(data = mtcars, aes(x = input$variable)) +
      geom_histogram(binwidth = 5, fill = "blue", color = "black") +
      labs(title = paste("Histogram of", input$variable),
           x = "Value",
           y = "Frequency")
  })
}

# Run the application
shinyApp(ui = ui, server = server)
```

